// Each game has independent stages. Difficulty is fixed when a run is created.
function missionStage(mode=selectedGame().id){return 1+Math.max(0,Number(profile.gameProgress?.[mode]?.clears)||0)}
function missionThreat(mode=selectedGame().id){return Math.min(10,1+Math.floor((playerLevel()-1)/7)+Math.floor((missionStage(mode)-1)/2)+(selectedMode().id==='expert'?2:selectedMode().id==='challenger'?1:0))}
function missionSummary(mode){return({arena:'Clear every wave and guardian',rally:'Beat rivals to the finish',leap:'Collect relics and reach the portal',tower:'Defend the crystal through every wave',dodge:'Collect stars and survive the storm',maze:'Find 3 relics and escape the warden',space:'Clear drones and defeat the guardian',memory:'Unlock every matching pair'})[mode]}
const TOWER_COURSE_PATHS=[[[20,150],[270,150],[270,430],[650,430],[650,220],[980,220]],[[20,130],[180,130],[180,480],[480,480],[480,210],[790,210],[790,450],[980,450]],[[20,310],[210,310],[210,120],[510,120],[510,480],[790,480],[790,260],[980,260]],[[20,130],[250,130],[250,350],[520,350],[520,150],[760,150],[760,480],[980,480]],[[20,100],[170,100],[170,500],[410,500],[410,220],[650,220],[650,480],[850,480],[850,330],[980,330]]];
function applyCourseGeometry(g,preview=false){const a=g.alt;if(!a)return;const i=g.map.baseIndex||0;
 if(a.type==='tower'){a.path=TOWER_COURSE_PATHS[i].map(p=>[...p]);a.slots=[];for(let y=100;y<560;y+=95)for(let x=90;x<940;x+=110)if(pathDistance(a.path,x,y)>62)a.slots.push({x,y});g.x=940;g.y=Math.min(560,a.path.at(-1)[1]+90);if(preview)a.towers=a.slots.filter((_,n)=>n%5===0).slice(0,3).map(p=>({...p,level:2,cooldown:0}))}
 if(a.type==='leap'){if(!preview){a.platforms=[];let x=0,y=530,n=0;while(x<a.goal+300){const w=n===0?280:170-i*8+miniRandom(a)*45;a.platforms.push({x,y,w,h:30,gem:n>0&&n%3===0,drone:n>0&&n%4===0});x+=w+50+i*9+miniRandom(a)*25;y=Math.max(310,Math.min(540,y+(miniRandom(a)-.5)*(85+i*8)));n++}a.goal=a.platforms.at(-1).x+60;g.x=85;g.y=500}a.platforms.forEach((p,n)=>{p.baseY=p.y;p.motion=(i===2||i===4)&&n>0&&n%3===1?12:0;if(n>0)p.drone=n%(i===4?3:4)===0});if(preview){a.platforms=[{x:0,y:530,w:260},{x:325+i*12,y:480-i*8,w:190-i*9,gem:true},{x:610+i*13,y:410+i*12,w:190-i*8,drone:true},{x:900,y:480,w:220,gem:true}];a.goal=970}}
 if(a.type==='memory'){a.pairs=Math.min(16,8+Math.floor((g.mission?.threat||1)/2)+(g.map.extraPairs||0));if(a.pairs%2)a.pairs++;a.cols=a.pairs/2;a.rows=4;a.goal=a.pairs;a.cards=shuffle(Array.from({length:a.pairs},(_,n)=>[n,n]).flat()).map((symbol,index)=>({symbol,index,matched:false}));a.preview=Math.max(1.5,3.6-(g.mission?.threat||1)*.18)}
}
const courseMiniInit=initialiseMini;initialiseMini=function(g,type){courseMiniInit(g,type);const threat=missionThreat(type);g.mission={type,stage:missionStage(type),threat,startHp:g.hp,complete:false};const a=g.alt;a.factor*=1+(threat-1)*.065;a.targetStars=5+threat;a.stars=0;a.collectibles=[];a.beams=[];a.beamClock=4;a.rivals=[0,0,0];a.checkpoints=0;a.hintsUsed=0;a.mistakes=0;a.combo=0;a.bestCombo=0;a.wardenClock=6;a.wardenIndex=0;
 if(type==='rally'){a.goal+=threat*350;a.gateSpacing=2000;a.nextGate=2000;g.time=Math.ceil(a.goal/((210+a.level*.7)*a.factor)*.96)+12}
 if(type==='leap'){a.relicGoal=Math.min(5,2+Math.floor(threat/3));a.platforms.forEach((p,n)=>{if(n>0&&n%3===0)p.gem=true});g.time=160-threaTweak(threat)}
 if(type==='tower'){a.maxWaves+=Math.floor(threat/3);g.time=240+threat*12}
 if(type==='dodge')g.time=65+threat*2;
 if(type==='space'){a.goal+=threat*3;a.bossDefeated=false;g.time=125+threat*3}
 if(type==='maze'){a.wardenIndex=a.exit;g.time=Math.max(150,mazeTourLength(a)*a.cell/110+40)}
 if(type==='memory')g.time=Math.max(90,155-threaTweak(threat));
 applyCourseGeometry(g);g.maxTime=g.time;
};
function threaTweak(t){return Math.min(30,t*3)}
function mazeRoute(a,start,end){const queue=[start],previous=new Map([[start,-1]]);for(let n=0;n<queue.length;n++){const cell=queue[n];if(cell===end)break;const x=cell%a.cols,y=Math.floor(cell/a.cols);[[0,-1],[1,0],[0,1],[-1,0]].forEach(([dx,dy],dir)=>{if(a.cells[cell].walls[dir])return;const nx=x+dx,ny=y+dy,j=ny*a.cols+nx;if(nx>=0&&nx<a.cols&&ny>=0&&ny<a.rows&&!previous.has(j)){previous.set(j,cell);queue.push(j)}})}if(!previous.has(end))return[];const path=[];for(let c=end;c!==start&&c!==-1;c=previous.get(c))path.unshift(c);return path}
function mazeTourLength(a){let last=0,length=0;for(const end of [...a.relics.map(r=>r.index),a.exit]){length+=mazeRoute(a,last,end).length;last=end}return length}
const courseMaze=makeRelicMaze;makeRelicMaze=function(g){g.alt.seed=(g.alt.seed+((g.map?.baseIndex||0)+1)*83731)>>>0;courseMaze(g)};
const missionArenaInit=initialiseMatch;initialiseMatch=function(g){missionArenaInit(g);const threat=live?(Number(live.config?.threat)||1):missionThreat('arena'),stage=live?(Number(live.config?.stage)||1):missionStage('arena');g.mission={type:'arena',stage,threat,startHp:g.hp};g.mode={...g.mode,perWave:g.mode.perWave+Math.floor(threat/3),waves:g.mode.waves+Math.floor(threat/4),speed:g.mode.speed*(1+(threat-1)*.025)};g.totalWaves=g.mode.waves;g.totalBots=g.totalWaves*g.mode.perWave+(g.mode.boss?1:0);g.time=g.mode.seconds+Math.floor(threat/3)*18;g.monsterBonus+=Math.floor(threat/2);g.maxTime=g.time};
const missionStart=startArena;startArena=function(subject){missionStart(subject);if(game&&!live){const g=game,m=g.mission;if(m)document.querySelector('#modal-content .feedback')?.insertAdjacentHTML('beforeend',`<br><b>Stage ${m.stage} · Threat ${m.threat}/10</b><br>${missionSummary(m.type)}.`)}};
const missionEnter=enterPreparedBattle;enterPreparedBattle=function(){missionEnter();const g=game;if(!g?.mission)return;g.mission.startHp=g.hp;document.querySelector('.arena-stage')?.insertAdjacentHTML('beforebegin',`<div class="mission-banner" id="mission-banner"><span><b>STAGE ${g.mission.stage} · THREAT ${g.mission.threat}/10</b><small>${missionSummary(g.mission.type)}</small></span><span id="mission-progress"></span></div>`)};
function missionStatus(g){const a=g.alt;if(!a)return `Waves ${g.wave}/${g.totalWaves}`;if(a.type==='rally'){const place=1+a.rivals.filter(d=>d>a.distance).length;return `POSITION ${place}/4 · Gates ${a.checkpoints}`}
 if(a.type==='leap')return `RELICS ${a.platforms.filter(p=>p.collected).length}/${a.relicGoal}`;
 if(a.type==='dodge')return `STARS ${a.stars}/${a.targetStars}`;
 if(a.type==='space')return a.bossDefeated?'GUARDIAN DEFEATED':a.guardian?'GUARDIAN '+Math.max(0,Math.ceil(a.guardian.hp))+' HP':`DRONES ${a.progress}/${a.goal}`;
 if(a.type==='memory')return `COMBO ${a.combo} · HINTS ${Math.max(0,2-a.hintsUsed)}`;
 if(a.type==='maze')return `RELICS ${a.progress}/3 · WARDEN ACTIVE`;
 return `WAVE ${a.wave}/${a.maxWaves}`}
const missionRender=renderArena;renderArena=function(g){missionRender(g);if(g.mission){const status=document.querySelector('#mission-progress');if(status&&g.elapsed-(g.mission.lastHUD||-1)>.2){g.mission.lastHUD=g.elapsed;status.textContent=missionStatus(g)}}};
const missionRally=updateRally;updateRally=function(g,dt,input){const a=g.alt,t=g.mission?.threat||1;a.rivals??=[0,0,0];a.rivals=a.rivals.map((d,i)=>d+(210+a.level*.7)*a.factor*(1.02+i*.035+t*.002)*dt);if(a.distance>=a.nextGate){a.checkpoints++;a.nextGate+=a.gateSpacing;a.score+=60;GameAudio.effect('pickup')}missionRally(g,dt,input)};
const missionDrawRally=drawRally;drawRally=function(c,g){missionDrawRally(c,g);const a=g.alt;for(const[d,i]of (a.rivals||[a.distance+90,a.distance+210,a.distance-130]).map((d,i)=>[d,i])){const y=g.y-(d-a.distance);if(y<-60||y>730)continue;const x=roadCentre(g,d)+[-95,0,95][i];roundRect(c,x-22,y-30,44,65,10,['#ff5379','#4ac8ff','#b6fb5a'][i],'#142241');roundRect(c,x-14,y-12,28,20,5,'#193457');c.fillStyle='#fff';c.font='bold 14px sans-serif';c.textAlign='center';c.fillText(i+1,x,y+43)}const gate=a.nextGate||2000,y=g.y-(gate-a.distance);if(y>-60&&y<650){const x=roadCentre(g,gate);c.strokeStyle='#fff174';c.lineWidth=8;c.beginPath();c.moveTo(x-170,y+25);c.lineTo(x-170,y-35);c.lineTo(x+170,y-35);c.lineTo(x+170,y+25);c.stroke();c.fillStyle='#15284a';c.font='bold 16px sans-serif';c.textAlign='center';c.fillText('CHECKPOINT',x,y-9)}};
const missionLeap=updateLeap;updateLeap=function(g,dt,input){for(const[p,n]of g.alt.platforms.map((p,n)=>[p,n]))if(p.motion)p.y=p.baseY+Math.sin(g.alt.clock*1.2+n)*p.motion;missionLeap(g,dt,input)};
const missionDodge=updateDodge;updateDodge=function(g,dt,input){const a=g.alt;missionDodge(g,dt,input);if(game!==g)return;a.beamClock-=dt;if(a.beamClock<=0){const vertical=(g.map.baseIndex||0)%2===0;a.beams.push({vertical,pos:vertical?g.x:g.y,age:0});a.beamClock=Math.max(2.7,5-(g.mission?.threat||1)*.2)}for(const b of a.beams){b.age+=dt;if(b.age>1.4&&b.age<1.75&&Math.abs((b.vertical?g.x:g.y)-b.pos)<25)miniDamage(g,2)}a.beams=a.beams.filter(b=>b.age<2);if(a.clock>(a.nextStar||0)){a.nextStar=a.clock+4;a.collectibles.push({x:90+miniRandom(a)*820,y:110+miniRandom(a)*400})}a.collectibles=a.collectibles.filter(p=>{if(Math.hypot(p.x-g.x,p.y-g.y)<38){a.stars++;a.score+=60;GameAudio.effect('pickup');return false}return true})};
const missionDrawDodge=drawDodge;drawDodge=function(c,g){missionDrawDodge(c,g);for(const p of g.alt.collectibles||[])miniGem(c,p.x,p.y,'#fff13a',18);for(const b of g.alt.beams||[]){c.fillStyle=b.age>1.4?'#ff436baa':'#ff436b33';c.strokeStyle='#ffec91';c.lineWidth=2;if(b.vertical){c.fillRect(b.pos-20,60,40,550);c.strokeRect(b.pos-20,60,40,550)}else{c.fillRect(40,b.pos-20,920,40);c.strokeRect(40,b.pos-20,920,40)}}};
const missionMaze=updateMaze;updateMaze=function(g,dt,input){missionMaze(g,dt,input);if(game!==g)return;const a=g.alt;a.wardenClock-=dt;if(a.hint>0||a.clock<5)return;if(a.wardenClock<=0){const x=Math.max(0,Math.min(a.cols-1,Math.floor((g.x-a.ox)/a.cell))),y=Math.max(0,Math.min(a.rows-1,Math.floor((g.y-a.oy)/a.cell))),target=y*a.cols+x;const path=mazeRoute(a,a.wardenIndex,target);if(path.length)a.wardenIndex=path[0];a.wardenClock=a.cell/(48+(g.mission?.threat||1)*3+(g.mission?.stage||1)*.14)}const p=mazePoint(a,a.wardenIndex);if(Math.hypot(p.x-g.x,p.y-g.y)<a.cell*.37){miniDamage(g,2);a.wardenClock=2}};
const missionDrawMaze=drawMaze;drawMaze=function(c,g){missionDrawMaze(c,g);const a=g.alt,p=mazePoint(a,a.wardenIndex??a.exit);roundRect(c,p.x-a.cell*.23,p.y-a.cell*.23,a.cell*.46,a.cell*.46,7,'#ff4d78','#fff7a5');ellipse(c,p.x-a.cell*.09,p.y,2,3,'#fff');ellipse(c,p.x+a.cell*.09,p.y,2,3,'#fff')};
const missionSpace=updateSpace;updateSpace=function(g,dt,input){const a=g.alt;if(a.progress>=a.goal&&!a.guardian&&!a.bossDefeated){const hp=(g.hero.damage||1)*(34+(g.mission?.threat||1)*6);a.guardian={x:500,y:100,hp,maxHp:hp,speed:0,fire:1,phase:0,guardian:true};a.objects.push(a.guardian)}if(a.guardian?.hp>0){a.guardian.x=500+Math.sin(a.clock*.8)*330;a.guardian.y=110+Math.sin(a.clock)*25;const before=a.guardian.fire;missionSpace(g,dt,input);if(a.guardian.fire>before){for(let i=-1;i<=1;i++)a.shots.push({x:a.guardian.x,y:a.guardian.y,dx:i*100,dy:170,life:5,enemy:true})}if(a.guardian.hp<=0)a.bossDefeated=true}else missionSpace(g,dt,input)};
const missionDrawSpace=drawSpace;drawSpace=function(c,g){missionDrawSpace(c,g);const b=g.alt.guardian;if(b?.hp>0){roundRect(c,b.x-65,b.y-30,130,70,20,'#ff456c','#fff37b');miniGem(c,b.x,b.y,'#ffe654',24);roundRect(c,280,35,440,16,7,'#132545');roundRect(c,280,35,440*Math.max(0,b.hp/b.maxHp),16,7,'#ff5b84');c.fillStyle='#fff';c.font='bold 15px sans-serif';c.textAlign='center';c.fillText('ORBIT GUARDIAN',500,28)}};
const missionMemory=memoryTap;memoryTap=function(g,x,y){const a=g.alt,before=a.progress;missionMemory(g,x,y);if(game!==g)return;if(a.progress>before){a.combo=(a.combo||0)+1;a.bestCombo=Math.max(a.bestCombo||0,a.combo);a.score+=a.combo*10}else if(a.lock>0){a.combo=0;a.mistakes=(a.mistakes||0)+1}};
const missionAction=miniAction;miniAction=function(g=game){if(g?.alt?.type==='memory'&&(g.alt.hintsUsed||0)>=2){toast('Two hints used. Trust your memory!');return}return missionAction(g)};
function missionMedals(g){return 1+Number(g.hp>=g.mission.startHp*.65)+Number(g.alt?.type==='dodge'?g.alt.stars>=g.alt.targetStars+2:g.time>=g.maxTime*.25)}
function recordMission(g){const m=g.mission;if(!m||m.complete)return;m.complete=true;const medals=missionMedals(g);profile.gameProgress??={};const previous=profile.gameProgress[m.type]||{};profile.gameProgress[m.type]={clears:Math.max(previous.clears||0,m.stage),bestMedals:Math.max(previous.bestMedals||0,medals)};save();return medals}
const missionFinishMini=finishMini;finishMini=function(win){const g=game;if(!g?.alt)return;const a=g.alt;if(win){if(a.type==='leap'&&a.platforms.filter(p=>p.collected).length<a.relicGoal){if(!a.portalNotice){toast('Collect '+a.relicGoal+' relics before entering the portal.');a.portalNotice=true}return}if(a.type==='space'&&!a.bossDefeated){if(a.guardian?.hp<=0)a.bossDefeated=true;else return}if(a.type==='dodge'&&a.stars<a.targetStars)win=false;if(a.type==='rally'&&a.rivals.filter(d=>d>a.distance).length>=3)win=false}const medals=win?recordMission(g):0;if(win)a.score+=medals*50;const stage=g.mission?.stage||1;missionFinishMini(win);if(win)document.querySelector('.results .notice')?.insertAdjacentHTML('beforebegin',`<p class="mission-medals" aria-label="${medals} out of 3 medals">${'★'.repeat(medals)}${'☆'.repeat(3-medals)}</p><p>Stage ${stage} cleared. Stage ${stage+1} unlocked! Medal points are included in your score.</p>`)};
const missionFinishArena=finishArena;finishArena=function(win){const g=game;if(g?.mission&&win)recordMission(g);return missionFinishArena(win)};

const missionHome=home;home=function(){const html=missionHome();if(selectedGame().id==='arena')return html;return html.replace(selectedMode().name.toUpperCase()+' · '+selectedMode().waves+' WAVES · '+selectedMode().seconds+'s PLAY TIME',selectedMode().name.toUpperCase()+' · STAGE '+missionStage()+' · '+courseMap().name.toUpperCase())};
if(!game&&!window.location.hash.startsWith('#room=')&&!window.location.hash.startsWith('#challenge='))navigate('home');
